<script setup>
import { ref,onMounted,onBeforeUnmount } from 'vue';
import { Link } from '@inertiajs/vue3';
import ListingGallery from '@/Components/Marketplace/ListingGallery.vue';
defineProps({item:Object,owner:Object});const emit=defineEmits(['close']);const dialog=ref(null);let previousOverflow;
onMounted(()=>{previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';dialog.value.showModal();});
onBeforeUnmount(()=>{dialog.value?.close();document.body.style.overflow=previousOverflow;});
function backdrop(event){if(event.target!==dialog.value)return;const b=dialog.value.getBoundingClientRect();if(event.clientX<b.left||event.clientX>b.right||event.clientY<b.top||event.clientY>b.bottom)dialog.value.close();}
const date=value=>value?new Date(value).toLocaleString('en-PH'):'Not available';
</script>
<template><Teleport to="body"><dialog ref="dialog" class="admin-listing-dialog" aria-labelledby="admin-listing-title" @close="emit('close')" @click="backdrop"><header><div><p>ADMIN LISTING INSPECTION</p><h2 id="admin-listing-title">{{ item.title }}</h2></div><button type="button" aria-label="Close listing inspection" autofocus @click="dialog.close()">×</button></header><div class="inspection-grid"><section class="inspection-main"><ListingGallery :photos="item.photos" :title="item.title" :service="item.service" :type="item.type"/><h3>Description</h3><p class="inspection-description">{{ item.description || 'No description provided.' }}</p><h3>Location</h3><p>{{ item.location.address || item.location.city || 'Not provided' }}</p><p v-if="item.location.lat != null && item.location.lng != null" class="inspection-muted">Coordinates: {{ item.location.lat }}, {{ item.location.lng }}</p><h3>Features & specifications</h3><ul><li v-for="feature in item.comparison?.features" :key="feature">{{ feature }}</li><li v-if="item.comparison?.scope">{{ item.comparison.scope }}</li></ul><dl><template v-for="(value,key) in item.details" :key="key"><dt>{{ key }}</dt><dd>{{ value }}</dd></template></dl></section><aside><span class="inspection-status">{{ item.sourceStatus }}</span><p class="inspection-price">{{ new Intl.NumberFormat('en-PH',{style:'currency',currency:item.currency}).format(item.price) }}<small>/ {{ item.priceUnit }}</small></p><h3>Record details</h3><dl><dt>Listing ID</dt><dd class="inspection-id">{{ item.id }}</dd><dt>Category</dt><dd>{{ {spaces:'Property',haul:'Vehicle',raketeer:'Raket / service'}[item.service] }}</dd><dt>Type</dt><dd>{{ item.type }}</dd><dt>Created</dt><dd>{{ date(item.createdAt) }}</dd><dt>Last updated</dt><dd>{{ date(item.updatedAt) }}</dd></dl><h3>Owner</h3><strong>{{ owner.name }}</strong><p class="inspection-muted">{{ owner.email }}</p><p>{{ item.providerApproved ? 'Provider role approved' : 'Provider role not approved' }}</p><p class="inspection-note">Role approval does not verify this individual listing.</p><Link :href="`/my-listings/${item.service}/${item.id}/edit`" class="inspection-edit">Edit listing →</Link><Link v-if="owner.id" :href="`/providers/${owner.id}`" class="inspection-profile">View public profile ↗</Link></aside></div><footer><span>Administrative view · includes unpublished listings</span><button type="button" @click="dialog.close()">Done</button></footer></dialog></Teleport></template>
<style scoped>
.admin-listing-dialog{margin:auto;width:min(1060px,calc(100% - 32px));max-height:calc(100dvh - 32px);border:0;border-radius:16px;padding:0;overflow:auto;background:white;color:#183e3b;font-family:Quicksand,sans-serif;overscroll-behavior:contain}.admin-listing-dialog::backdrop{background:#082c2980}.admin-listing-dialog header{display:flex;align-items:flex-start;gap:20px;justify-content:space-between;padding:22px 28px;border-bottom:1px solid #dce7e4}.admin-listing-dialog header p{font-size:10px;letter-spacing:.1em;font-weight:700;color:#637b76;margin:0 0 8px}.admin-listing-dialog h2{font-size:24px;font-weight:700;line-height:1.3;overflow-wrap:anywhere}.admin-listing-dialog header button{width:44px;height:44px;flex-shrink:0;font-size:28px}.inspection-grid{display:grid;grid-template-columns:minmax(0,1fr) 300px}.inspection-main{padding:28px;min-width:0}.inspection-grid aside{padding:28px;background:#f4f8f6;border-left:1px solid #dce7e4;min-width:0}.admin-listing-dialog h3{font-size:14px;font-weight:700;margin:24px 0 10px}.admin-listing-dialog p,.admin-listing-dialog li{font-size:13px;line-height:1.7;overflow-wrap:anywhere}.inspection-description{white-space:pre-wrap}.inspection-status{display:inline-block;background:#dcece7;color:#12675f;border-radius:6px;padding:5px 10px;font-size:12px;font-weight:700;text-transform:capitalize}.inspection-grid .inspection-price{font-size:24px;font-weight:700;margin:16px 0}.inspection-price small{display:block;font-size:12px;font-weight:500}.admin-listing-dialog dl{font-size:12px}.admin-listing-dialog dt{color:#637b76;margin-top:12px}.admin-listing-dialog dd{margin:3px 0;overflow-wrap:anywhere;font-weight:600}.inspection-id{font-family:monospace}.inspection-muted,.inspection-note{color:#637b76}.inspection-note{font-size:11px!important}.inspection-edit{display:block;border-radius:8px;background:#137671;color:white;padding:12px;text-align:center;font-size:13px;font-weight:700;margin-top:24px}.inspection-profile{display:block;text-align:center;padding:12px;font-size:12px}.admin-listing-dialog footer{display:flex;justify-content:space-between;align-items:center;gap:12px;border-top:1px solid #dce7e4;padding:16px 28px;font-size:11px;color:#637b76}.admin-listing-dialog footer button{padding:10px 20px;border:1px solid #b7d8d0;border-radius:8px;color:#183e3b;font-weight:700}.admin-listing-dialog :is(button,a):focus-visible{outline:2px solid #137671;outline-offset:3px}@media(max-width:700px){.inspection-grid{grid-template-columns:1fr}.inspection-grid aside{border-left:0;border-top:1px solid #dce7e4}.admin-listing-dialog header,.inspection-main,.inspection-grid aside{padding:20px}.admin-listing-dialog h2{font-size:21px}.admin-listing-dialog footer{padding:16px 20px}}
</style>
